<?php require_once __DIR__.'/include/config.php';require_once __DIR__.'/include/billing.php';hms_start_session();hms_require_role('patient');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;if(!hms_billing_ready($con))exit(hms_billing_notice());$invoice=hms_db_query($con,'SELECT * FROM billing_invoices WHERE id=? AND patient_user_id=?',[$id,(int)$_SESSION['id']])->fetch_assoc();if(!$invoice){http_response_code(404);exit('Invoice not found.');}$items=hms_db_query($con,'SELECT * FROM billing_invoice_items WHERE invoice_id=?',[$id]);$payments=hms_db_query($con,'SELECT * FROM billing_payments WHERE invoice_id=? ORDER BY received_at DESC',[$id]);?>
<!doctype html><html><head><meta charset="utf-8"><title><?=hms_h($invoice['invoice_number'])?></title><link rel="stylesheet" href="vendor/bootstrap/css/bootstrap.min.css"><style>@media print{button,a{display:none}}main{max-width:850px;margin:25px auto}</style></head><body><main><a href="billing.php">Back</a><button onclick="print()" class="btn btn-primary pull-right">Print invoice</button><h1>MedTech Hospital</h1><h2>Invoice <?=hms_h($invoice['invoice_number'])?></h2><table class="table table-bordered"><tr><th>Service</th><th>Qty</th><th>Unit price</th><th>Total</th></tr><?php while($item=$items->fetch_assoc()):?><tr><td><?=hms_h($item['description'])?></td><td><?=hms_h($item['quantity'])?></td><td>₹<?=number_format((float)$item['unit_price'],2)?></td><td>₹<?=number_format((float)$item['line_total'],2)?></td></tr><?php endwhile;?></table><p><b>Total ₹<?=number_format((float)$invoice['total_amount'],2)?> · Paid ₹<?=number_format((float)$invoice['amount_paid'],2)?> · Outstanding ₹<?=number_format((float)$invoice['balance_amount'],2)?></b></p><h3>Payment history</h3><table class="table"><tr><th>Receipt</th><th>Date</th><th>Amount</th><th>Method</th></tr><?php while($payment=$payments->fetch_assoc()):?><tr><td><a href="receipt.php?id=<?=hms_h($payment['id'])?>"><?=hms_h($payment['receipt_number'])?></a></td><td><?=hms_h($payment['received_at'])?></td><td>₹<?=number_format((float)$payment['amount'],2)?></td><td><?=hms_h($payment['payment_method'])?></td></tr><?php endwhile;?></table></main></body></html>
